/// Branch to a trap block if `cond` is true, continuing in a fresh block.
pub fn branch_trap(&mut self, cond: &Val, code: i32) {
    let trap = self.trap_block(code);
    let cont = self.fresh_label();
    self.emit(format!(
        "br i1 {}, label %{}, label %{}",
        cond.s, trap, cont
    ));
    self.start_block(&cont);
}

