import random, os
rng=random.Random(1)
parts=['(module (memory (export "memory") 1 16)']
NF=1000
for i in range(NF):
    body=[]
    body.append('(local $a i32) (local $b i64) (local $v v128)')
    body.append(f'(local.set $a (local.get 0))')
    for j in range(100):
        k=rng.randrange(8)
        if k==0: body.append('(local.set $a (i32.add (local.get $a) (i32.const 7)))')
        elif k==1: body.append('(local.set $a (i32.mul (local.get $a) (i32.const 3)))')
        elif k==2: body.append('(local.set $a (i32.xor (local.get $a) (i32.shr_u (local.get $a) (i32.const 5))))')
        elif k==3: body.append('(local.set $b (i64.add (local.get $b) (i64.extend_i32_s (local.get $a))))')
        elif k==4: body.append('(local.set $v (i32x4.add (local.get $v) (i32x4.splat (local.get $a))))')
        elif k==5: body.append('(local.set $a (i32.load offset=16 (local.get $a)))') if False else body.append('(local.set $a (i32.add (local.get $a) (i32.load8_u offset=16 (i32.and (local.get $a) (i32.const 1023)))))')
        elif k==6: body.append('(i32.store8 offset=32 (i32.and (local.get $a) (i32.const 1023)) (local.get $a))')
        else: body.append('(local.set $a (select (local.get $a) (i32.const 5) (i32.gt_s (local.get $a) (i32.const 100))))')
    body.append('(i32.add (local.get $a) (i32.wrap_i64 (local.get $b)))')
    parts.append(f'(func $f{i} (param i32) (result i32) '+' '.join(body)+')')
# exported dispatcher calling a few
parts.append('(func (export "run") (param i32 i32) (result i32) (local $s i32)')
parts.append('(local.set $s (i32.const 0))')
for i in range(0,NF,37):
    parts.append(f'(local.set $s (i32.add (local.get $s) (call $f{i} (local.get 0))))')
parts.append('(i32.add (local.get $s) (local.get 1)))')
parts.append(')')
s='\n'.join(parts)
open(os.path.join(os.environ['TMPDIR'],'large.wat'),'w').write(s)
print('wat bytes', len(s))
